# Expected values generated by test/pandas/gen_expected.py (pandas 3.1.1).

import numpy as np
import pandas as pd
import hashlib

def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

def _r(x) -> str:
    if isinstance(x, pd.Scalar):
        return repr(x.f) if x.kind == 0 else (repr(x.s) if x.kind == 3 else str(x))
    elif isinstance(x, float) or isinstance(x, str):
        return repr(x)
    else:
        return str(x)

@test
def test_frame():
    F = make_F(40, 8)
    y = make_y(40)
    df = pd.DataFrame(F, columns=[f"ch{i}" for i in range(F.shape[1])])
    df["label"] = y
    g = df.groupby("label").mean()
    d = df.drop(columns="label").describe()
    c = df.drop(columns="label").corr()
    csv = df.to_csv(float_format="%.17g")

    F2 = make_F(13, 4, seed=777)
    F2[3, 1] = float("nan")
    F2[7, 2] = float("nan")
    d2 = pd.DataFrame(F2, columns=["a", "b", "c", "d"])
    d2["k"] = np.array([i % 3 for i in range(13)], dtype=int)

    s3 = pd.DataFrame({"name": pd.Series(["b", "a", "c", "a", "b", "b"]), "v": pd.Series([1, 2, 3, 4, 5, 6]), "w": pd.Series([0.5, 1.5, 2.5, 3.5, 4.5, 5.5])})

    r = pd.DataFrame(make_F(25, 3, seed=99), columns=["x", "y", "z"])

    f = pd.DataFrame({"a": pd.Series([3, 1, 2, 5, 4]), "b": pd.Series([0.5, 2.25, -1.0, 3.5, 0.0]), "s": pd.Series(["x", "y,z", "w", 'q"t', "x"])})
    assert f.to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert f.to_csv(index=False) == 'a,b,s\n3,0.5,x\n1,2.25,"y,z"\n2,-1.0,w\n5,3.5,"q""t"\n4,0.0,x\n'
    assert f.to_csv(sep=";", header=False) == '0;3;0.5;x\n1;1;2.25;y,z\n2;2;-1.0;w\n3;5;3.5;"q""t"\n4;4;0.0;x\n'
    assert f.sort_values("b").to_csv() == ',a,b,s\n2,2,-1.0,w\n4,4,0.0,x\n0,3,0.5,x\n1,1,2.25,"y,z"\n3,5,3.5,"q""t"\n'
    assert f.sort_values("a", ascending=False).to_csv() == ',a,b,s\n3,5,3.5,"q""t"\n4,4,0.0,x\n0,3,0.5,x\n2,2,-1.0,w\n1,1,2.25,"y,z"\n'
    assert f.sort_values("s").to_csv() == ',a,b,s\n3,5,3.5,"q""t"\n2,2,-1.0,w\n0,3,0.5,x\n4,4,0.0,x\n1,1,2.25,"y,z"\n'
    assert f.sort_values(["s", "a"]).to_csv() == ',a,b,s\n3,5,3.5,"q""t"\n2,2,-1.0,w\n0,3,0.5,x\n4,4,0.0,x\n1,1,2.25,"y,z"\n'
    assert f.set_index("s").to_csv() == 's,a,b\nx,3,0.5\n"y,z",1,2.25\nw,2,-1.0\n"q""t",5,3.5\nx,4,0.0\n'
    assert f.set_index("a").reset_index().to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert f.set_index("a").sort_index().to_csv() == 'a,b,s\n1,2.25,"y,z"\n2,-1.0,w\n3,0.5,x\n4,0.0,x\n5,3.5,"q""t"\n'
    assert f[f["b"] > 0.25].to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n3,5,3.5,"q""t"\n'
    assert f[["s", "a"]].to_csv() == ',s,a\n0,x,3\n1,"y,z",1\n2,w,2\n3,"q""t",5\n4,x,4\n'
    assert f.iloc[1:4].to_csv() == ',a,b,s\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n'
    assert f.loc[1:3, ["a", "b"]].to_csv() == ',a,b\n1,1,2.25\n2,2,-1.0\n3,5,3.5\n'
    assert f.head(2).to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n'
    assert f.tail(2).to_csv() == ',a,b,s\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert f.rename(columns={"a": "A"}).to_csv() == ',A,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert f[["a", "b"]].astype(float).to_csv() == ',a,b\n0,3.0,0.5\n1,1.0,2.25\n2,2.0,-1.0\n3,5.0,3.5\n4,4.0,0.0\n'
    assert f.drop(index=[0, 2]).to_csv() == ',a,b,s\n1,1,2.25,"y,z"\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert f.drop("b", axis=1).to_csv() == ',a,s\n0,3,x\n1,1,"y,z"\n2,2,w\n3,5,"q""t"\n4,4,x\n'
    assert (f["a"] * 2 + f["b"]).to_csv() == ',0\n0,6.5\n1,4.25\n2,3.0\n3,13.5\n4,8.0\n'
    assert (f["a"] * 2 + 1).to_csv() == ',a\n0,7\n1,3\n2,5\n3,11\n4,9\n'
    assert (f["a"] / 2).to_csv() == ',a\n0,1.5\n1,0.5\n2,1.0\n3,2.5\n4,2.0\n'
    assert f[["a", "b"]].apply(lambda s: s.max() - s.min()).to_csv() == ',0\na,4.0\nb,4.5\n'
    assert f[["a", "b"]].apply(lambda r: r["a"] * r["b"], axis=1).to_csv() == ',0\n0,1.5\n1,2.25\n2,-2.0\n3,17.5\n4,0.0\n'
    assert f["a"].map(lambda v: v * 10).to_csv() == ',a\n0,30\n1,10\n2,20\n3,50\n4,40\n'
    assert f["s"].map({"x": 1.5, "w": 2.5}).to_csv() == ',s\n0,1.5\n1,\n2,2.5\n3,\n4,1.5\n'
    assert pd.concat([f, f]).to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n'
    assert pd.concat([f[["a"]], f[["b"]]], axis=1).to_csv() == ',a,b\n0,3,0.5\n1,1,2.25\n2,2,-1.0\n3,5,3.5\n4,4,0.0\n'
    assert pd.concat([f, f], ignore_index=True).to_csv() == ',a,b,s\n0,3,0.5,x\n1,1,2.25,"y,z"\n2,2,-1.0,w\n3,5,3.5,"q""t"\n4,4,0.0,x\n5,3,0.5,x\n6,1,2.25,"y,z"\n7,2,-1.0,w\n8,5,3.5,"q""t"\n9,4,0.0,x\n'
    left = pd.DataFrame({"key": pd.Series([1, 2, 3, 4]), "lv": pd.Series([0.1, 0.2, 0.3, 0.4])})
    right = pd.DataFrame({"key": pd.Series([2, 4, 4, 5]), "rv": pd.Series(["p", "q", "r", "s"])})
    assert pd.merge(left, right, on="key").to_csv() == ',key,lv,rv\n0,2,0.2,p\n1,4,0.4,q\n2,4,0.4,r\n'
    assert pd.merge(left, right, on="key", how="left").to_csv() == ',key,lv,rv\n0,1,0.1,\n1,2,0.2,p\n2,3,0.3,\n3,4,0.4,q\n4,4,0.4,r\n'
    assert pd.merge(left, right, on="key", how="outer").to_csv() == ',key,lv,rv\n0,1,0.1,\n1,2,0.2,p\n2,3,0.3,\n3,4,0.4,q\n4,4,0.4,r\n5,5,,s\n'
    assert [_r(x) for x in [str(x) for x in f["s"].unique()]] == [_r(x) for x in ['x', 'y,z', 'w', 'q"t']]
    assert [_r(x) for x in [str(x) for x in f.dtypes]] == [_r(x) for x in ['int64', 'float64', 'str']]
    assert f[["a", "b"]].T.to_csv() == ',0,1,2,3,4\na,3.0,1.0,2.0,5.0,4.0\nb,0.5,2.25,-1.0,3.5,0.0\n'
    assert f["s"].isin(["x", "w"]).to_csv() == ',s\n0,True\n1,False\n2,True\n3,False\n4,True\n'
    assert f.to_csv(float_format="%.3f", na_rep="NA") == ',a,b,s\n0,3,0.500,x\n1,1,2.250,"y,z"\n2,2,-1.000,w\n3,5,3.500,"q""t"\n4,4,0.000,x\n'
    fn = pd.DataFrame({"v": pd.Series([1.0, float("nan"), 3.0]), "s": pd.Series([pd.Scalar.of("a"), pd.Scalar.of(None), pd.Scalar.of("c")])})
    assert fn.to_csv(na_rep="NA") == ',v,s\n0,1.0,a\n1,NA,NA\n2,3.0,c\n'
    assert pd.Series([1.5, 2.5], name="v").to_csv() == ',v\n0,1.5\n1,2.5\n'
    assert pd.Series([1, 2]).to_csv() == ',0\n0,1\n1,2\n'
    assert pd.Series({"a": 1.0, "b": 2.0}).to_csv() == ',0\na,1.0\nb,2.0\n'
    sa = pd.Series([1.0, 2.0, 3.0], index=["a", "b", "c"])
    sb = pd.Series([10.0, 20.0, 30.0], index=["b", "c", "d"])
    assert (sa + sb).to_csv() == ',0\na,\nb,12.0\nc,23.0\nd,\n'
    assert pd.Series([1, 3, 2, 5, 4]).cummax().to_csv() == ',0\n0,1\n1,3\n2,3\n3,5\n4,5\n'
    assert pd.Series([3.0, 1.0, 3.0, 2.0]).rank().to_csv() == ',0\n0,3.5\n1,1.0\n2,3.5\n3,2.0\n'
    assert pd.Series([float("inf"), -float("inf"), 1e300, 1e-300, 123456789.0, 0.1]).to_csv() == ',0\n0,inf\n1,-inf\n2,1e+300\n3,1e-300\n4,123456789.0\n5,0.1\n'

    print("test_frame: ok")

test_frame()
